import ctypes
import os

# Load the libraries in the correct order
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the necessary ctypes structures and constants
class GSLComplex(ctypes.Structure):
    _fields_ = [
        ("dat", ctypes.c_double * 2)  # Real and imaginary parts
    ]

class GSLFFTWaveTable(ctypes.Structure):
    _fields_ = [
        ("n", ctypes.c_size_t),
        ("trig", ctypes.POINTER(GSLComplex)),
        ("factor", ctypes.c_size_t * 64),
        ("twiddle", ctypes.POINTER(ctypes.POINTER(GSLComplex)) * 64),
        ("nf", ctypes.c_size_t)
    ]

# Define the function prototype for gsl_fft_halfcomplex_wavetable_alloc
gsl.gsl_fft_halfcomplex_wavetable_alloc.argtypes = [ctypes.c_size_t]
gsl.gsl_fft_halfcomplex_wavetable_alloc.restype = ctypes.POINTER(GSLFFTWaveTable)

def allocate_fft_wavetable(n):
    if n <= 0:
        raise ValueError("Input n must be a positive integer.")

    wavetable = gsl.gsl_fft_halfcomplex_wavetable_alloc(n)

    if not wavetable:
        raise MemoryError("Failed to allocate FFT wavetable.")

    return wavetable

def free_fft_wavetable(wavetable):
    if wavetable:
        gsl.gsl_fft_halfcomplex_wavetable_free(wavetable)

def assert_test():
    try:
        # Test case 1: Valid input
        n = 16
        wavetable = allocate_fft_wavetable(n)
        assert wavetable.contents.n == n, "Wavetable size mismatch."
        free_fft_wavetable(wavetable)

        # Test case 2: Invalid input (negative n)
        try:
            allocate_fft_wavetable(-5)
        except ValueError as e:
            assert str(e) == "Input n must be a positive integer.", "Incorrect error message for negative n."

        # Test case 3: Invalid input (zero n)
        try:
            allocate_fft_wavetable(0)
        except ValueError as e:
            assert str(e) == "Input n must be a positive integer.", "Incorrect error message for zero n."

        print("All tests passed.")
    except AssertionError as e:
        print(f"Test failed: {e}")

if __name__ == "__main__":
    assert_test()
